index = invert(doc_vectors)  # term to [(doc, weight)]
q = encode_query("auto repair")   # {term: weight}
acc = defaultdict(float)
for term, qw in q.items():
    for doc, dw in index[term]:
        acc[doc] += qw * dw
top = sorted(acc.items(), key=lambda kv: -kv[1])[:k]

# offline: documents reordered so similar ones get neighboring IDs,
# then cut into blocks of b consecutive IDs (here b = 4)
blocks = {"B0": [D1, D4, D5, D6], "B1": [D2, D7, D8, D9],
          "B2": [D3, D10, D11, D12]}
bmax[t][B] = max weight of term t in block B   # 0 if absent

# query time, k = 2
ub = {B: sum(qw * bmax[t][B] for t, qw in q.items()) for B in blocks}
heap = []                                  # best k exact scores
for B in sorted(blocks, key=lambda B: -ub[B]):
    theta = kth_best(heap, k)              # 0 until k scores exist
    if theta >= ub[B]:
        break                              # safe: nothing left can win
    for d in blocks[B]:
        push(heap, dot(q, vec[d]), k)      # exact scores, forward index
return sorted(heap, reverse=True)
